// Native SPS gate TB (P2 SPS-only): H=32 W=32 C0=3 C1=96 C2=384 T=4.
// 64 tokens x 48 groups = 3072 token beats; beat = 8 lanes x T=4 x RW=4 nibbles
// (adapter expanded 0/1).
// Golden/vectors: build/spikformer/vision_ref_20261031/vectors/sps_native_tc2_8
// generated by scripts/spikformer/gen_sps_param.py --h 32 --w 32 --c1 96
// --c2 384 --t 4 --seed 7 --tc2 8 (RTL native uses TC2=8 in
// spiking_eyeriss_array; the older sps_native set is tc2=4 and its w_sched
// tile permutation does not match the TC2=8 array -> only w_sched.hex differs;
// w_ld1/b_ld/pix/exp/w_uniq are byte-identical, sha256 verified 2026-10-31).
// Host stream order matches tb_sps_ref_small (SPS-only):
//   w_ld1(324) -> b_ld(384) -> pix(1024) -> w_sched(41472; (g2,tile) order).
// Checker: every expanded nibble vs exp.hex char = lane, bit t = spike time;
// last only on beat 3071; done sticky; watchdog. Structural assertions
// (read-only hierarchical probes, no force): psum capture order
// (grp,pos) == (cap_n/256, cap_n%256) with capture total (H1*W1)*G2=12288;
// flush row order n -> (p2_g,p2_y) == (n/H1, n%H1) with total G2*H1=768 and
// p2cnt==ROWW at flush entry; no pad-flush residue at C_C2FL.
// Dumps got beats to sim/tb_sps_native_gotbeats_imgnative_20261031.hex.
`timescale 1ns/1ps
module tb_sps_native;
  reg s_clk = 0, s_rst = 1, start = 0;
  always #5 s_clk = ~s_clk;
  reg [63:0] wdata; reg wvalid; wire wready;
  reg [23:0] pdata; reg pvalid; wire pready;
  reg [15:0] thr1 = 200, thr2 = 60;
  wire [127:0] tdata; wire tvalid, tlast; reg tready = 1;
  wire done;
  spiking_sps_ref_top #(.H(32), .W_IN(32), .C0(3), .C1(96), .C2(384),
    .T(4), .LANES(8), .TC2(8), .WT_W(8), .ACC_W(21), .RW(4)) dut (
    .s_clk(s_clk), .s_rst(s_rst), .i_thr_1(thr1), .i_thr_2(thr2),
    .i_weight_in(wdata), .i_weight_valid(wvalid), .o_weight_ready(wready),
    .i_pix_valid(pvalid), .o_pix_ready(pready), .i_pix_data(pdata),
    .i_start(start), .o_done(done),
    .o_tok_data(tdata), .o_tok_valid(tvalid), .i_tok_ready(tready), .o_tok_last(tlast)
  );
  localparam int NW1 = 324, NBB = 384, NPIX = 1024, NSCH = 41472, NBEAT = 3072;
  localparam int NCAP = 12288, NFLUSH = 768, ROWW = 16, H1 = 16, NPOS = 256, G2 = 48;
  reg [63:0] w_ld1  [0:NW1-1];
  reg [63:0] b_ld   [0:NBB-1];
  reg [63:0] w_sched[0:NSCH-1];
  reg [23:0] pix    [0:NPIX-1];
  reg [31:0] expw   [0:NBEAT-1];
  reg [127:0] gotb  [0:NBEAT-1];
  integer i, k, tt, got, fails, shown, ncy;
  integer cap_n, flush_n, struct_fails, prev_st, drain_seen;
  integer fd, dmp;
  reg [15:0] pos, g;
  reg [7:0]  xx, yy;
  initial begin
    $readmemh("D:/dl_snn/build/spikformer/vision_ref_20261031/vectors/sps_native_tc2_8/w_ld1.hex", w_ld1);
    $readmemh("D:/dl_snn/build/spikformer/vision_ref_20261031/vectors/sps_native_tc2_8/b_ld.hex", b_ld);
    $readmemh("D:/dl_snn/build/spikformer/vision_ref_20261031/vectors/sps_native_tc2_8/w_sched.hex", w_sched);
    $readmemh("D:/dl_snn/build/spikformer/vision_ref_20261031/vectors/sps_native_tc2_8/pix.hex", pix);
    $readmemh("D:/dl_snn/build/spikformer/vision_ref_20261031/vectors/sps_native_tc2_8/exp.hex", expw);
    $display("TB_PARAMS H=32 W=32 C1=96 C2=384 T=4 TC2=8 beats=%0d w1=%0d bias=%0d pix=%0d sched=%0d thr1=%0d thr2=%0d",
      NBEAT, NW1, NBB, NPIX, NSCH, thr1, thr2);
    wvalid = 0; pvalid = 0; fails = 0; got = 0; shown = 0; ncy = 0;
    repeat (4) @(posedge s_clk); s_rst = 0;
    @(posedge s_clk); start = 1; @(posedge s_clk); start = 0;
    // host stream 1: conv1 weights
    for (i = 0; i < NW1; i = i + 1) begin
      @(posedge s_clk); #1; wdata = w_ld1[i]; wvalid = 1;
      do @(posedge s_clk); while (!(wvalid && wready));
      #1; wvalid = 0;
    end
    // host stream 2: bias pairs (21b lo/hi)
    for (i = 0; i < NBB; i = i + 1) begin
      @(posedge s_clk); #1; wdata = b_ld[i]; wvalid = 1;
      do @(posedge s_clk); while (!(wvalid && wready));
      #1; wvalid = 0;
    end
    // host stream 3: pixels (h*w, 3x8b)
    for (i = 0; i < NPIX; i = i + 1) begin
      @(posedge s_clk); #1; pdata = pix[i]; pvalid = 1;
      do @(posedge s_clk); while (!(pvalid && pready));
      #1; pvalid = 0;
    end
    // host stream 4: conv2 tile weights in (g2,tile) schedule order
    for (i = 0; i < NSCH; i = i + 1) begin
      @(posedge s_clk); #1; wdata = w_sched[i]; wvalid = 1;
      do @(posedge s_clk); while (!(wvalid && wready));
      #1; wvalid = 0;
    end
    $display("HOST_STREAM_DONE cyc=%0d", ncy);
  end
  // progress monitor
  always @(posedge s_clk) begin
    ncy = ncy + 1;
    if ((ncy % 200000) == 0)
      $display("MON cyc=%0d ctrl_st=%0d got=%0d fails=%0d done=%b wready=%b pready=%b tokv=%b",
        ncy, dut.u_ctrl.st, got, fails, done, wready, pready, tvalid);
  end
  // structural assertions (read-only hierarchical probes; no force)
  initial begin
    cap_n = 0; flush_n = 0; struct_fails = 0; prev_st = 0; drain_seen = 0;
  end
  always @(posedge s_clk) begin
    prev_st <= dut.u_ctrl.st;
    if (!s_rst) begin
      // psum beat capture order: row-major (grp,pos)
      if (dut.u_ctrl.i_psum_beat_valid && dut.u_ctrl.o_psum_beat_ready) begin
        if ((dut.u_ctrl.i_psum_beat_pos !== (cap_n % NPOS)) ||
            (dut.u_ctrl.i_psum_beat_grp !== (cap_n / NPOS))) begin
          struct_fails = struct_fails + 1;
          if (struct_fails < 8)
            $display("STRUCTFAIL capture cap_n=%0d pos=%0d want=%0d grp=%0d want=%0d",
              cap_n, dut.u_ctrl.i_psum_beat_pos, cap_n % NPOS,
              dut.u_ctrl.i_psum_beat_grp, cap_n / NPOS);
        end
        cap_n = cap_n + 1;
      end
      // prow2 row flush: detect entry into C_C2W (state 9) and check the
      // latched row identity is row-major (p2_g,p2_y); count one per flush.
      if ((dut.u_ctrl.st == 9) && (prev_st != 9)) begin
        if (dut.u_ctrl.p2cnt !== ROWW) begin
          struct_fails = struct_fails + 1;
          if (struct_fails < 8) $display("STRUCTFAIL flush p2cnt=%0d want=%0d n=%0d", dut.u_ctrl.p2cnt, ROWW, flush_n);
        end
        if ((dut.u_ctrl.p2_g !== (flush_n / H1)) || (dut.u_ctrl.p2_y !== (flush_n % H1))) begin
          struct_fails = struct_fails + 1;
          if (struct_fails < 8) $display("STRUCTFAIL flush n=%0d p2_g=%0d want=%0d p2_y=%0d want=%0d",
            flush_n, dut.u_ctrl.p2_g, flush_n / H1, dut.u_ctrl.p2_y, flush_n % H1);
        end
        flush_n = flush_n + 1;
      end
      // C_DRAIN entry (state 11): no pad-flush residue may remain
      if ((dut.u_ctrl.st == 11) && (prev_st != 11) && !drain_seen) begin
        drain_seen = 1;
        if ((dut.u_ctrl.beat_pushed !== NCAP) || (dut.u_ctrl.p2cnt !== 0)) begin
          struct_fails = struct_fails + 1;
          $display("STRUCTFAIL drain beat_pushed=%0d want=%0d p2cnt=%0d", dut.u_ctrl.beat_pushed, NCAP, dut.u_ctrl.p2cnt);
        end
      end
    end
  end
  // beat checker + watchdog
  initial begin
    @(negedge s_rst);
    fork : watch
      begin
        while (got < NBEAT) begin
          @(posedge s_clk);
          if (tvalid && tready) begin
            gotb[got] = tdata;
            pos = got / 48; g = got % 48; xx = pos % 8; yy = pos / 8;
            for (k = 0; k < 8; k = k + 1) begin
              for (tt = 0; tt < 4; tt = tt + 1) begin
                if (tdata[((k*4+tt)+1)*4-1 -: 4] !== {3'b0, expw[got][4*(7-k)+tt]}) begin
                  fails = fails + 1;
                  if (shown < 24) begin
                    $display("BEATFAIL beat=%0d pos=%0d x=%0d y=%0d g=%0d lane=%0d t=%0d bit=%0d got=%0d want=%0d gotword=%h expword=%h st=%0d p2cnt=%0d p2_g=%0d p2_y=%0d cap_n=%0d flush_n=%0d",
                      got, pos, xx, yy, g, k, tt, (k*4+tt), tdata[((k*4+tt)+1)*4-1 -: 4],
                      expw[got][4*(7-k)+tt], tdata, expw[got], dut.u_ctrl.st,
                      dut.u_ctrl.p2cnt, dut.u_ctrl.p2_g, dut.u_ctrl.p2_y, cap_n, flush_n);
                    shown = shown + 1;
                  end
                end
              end
            end
            if ((got == NBEAT-1) && !tlast) begin $display("LAST missing on beat %0d", got); fails = fails + 1; end
            if ((got < NBEAT-1) && tlast) begin $display("LAST early on beat %0d", got); fails = fails + 1; end
            if ((got % 512) == 0) $display("PROGRESS beat=%0d cyc=%0d fails=%0d cap_n=%0d flush_n=%0d", got, ncy, fails, cap_n, flush_n);
            got = got + 1;
          end
        end
        wait (done);
        $display("DONE_ASSERTED_BEATS=%0d cyc=%0d", got, ncy);
      end
      begin
        repeat (12000000) @(posedge s_clk);
        $display("FAIL timeout: got=%0d done=%b ctrl_st=%0d cap_n=%0d flush_n=%0d", got, done, dut.u_ctrl.st, cap_n, flush_n);
        fails = fails + 1;
      end
    join_any
    disable fork;
    // final structural totals
    if (cap_n !== NCAP) begin $display("STRUCTFAIL capture total=%0d want=%0d", cap_n, NCAP); struct_fails = struct_fails + 1; end
    if (flush_n !== NFLUSH) begin $display("STRUCTFAIL flush total=%0d want=%0d", flush_n, NFLUSH); struct_fails = struct_fails + 1; end
    if (drain_seen == 0) begin $display("STRUCTFAIL C_DRAIN never entered"); struct_fails = struct_fails + 1; end
    $display("STRUCT capture=%0d flush=%0d fails=%0d", cap_n, flush_n, struct_fails);
    // dump got beats (hex, 128b per line) for offline diff
    dmp = $fopen("D:/dl_snn/build/spikformer/vision_ref_20261031/sim/tb_sps_native_gotbeats_imgnative_20261031.hex", "w");
    for (i = 0; i < got; i = i + 1) $fwrite(dmp, "%032h\n", gotb[i]);
    $fclose(dmp);
    if (fails == 0 && struct_fails == 0 && got == NBEAT)
      $display("ALL PASS tb_sps_native (%0d beats; capture=%0d flush=%0d structural ok)", NBEAT, cap_n, flush_n);
    else $display("FAILURES=%0d struct_fails=%0d got=%0d tb_sps_native", fails, struct_fails, got);
    $finish;
  end
endmodule
